#include <iostream>

int main() {
    std::ios::sync_with_stdio(false);
    std::cin.tie(nullptr);

    int n;
    std::cin >> n;

    long long total = 0;              // up to 10^14; an int holds 2.1 * 10^9
    for (int i = 0; i < n; ++i) {
        int value;                    // each value fits in an int
        std::cin >> value;
        total += value;
    }

    std::cout << total << '\n';
}
